-- Every team MLB's feed can send, in teamid_universe_mapping with an official
-- level and in team_id_map (MLB team id -> teamid), so no stat line from the
-- MLB feed ever lands without a team and a level. Applied Oct 27, 2026 at
-- Pete's direction ("teamid_universe_mapping should be 100% complete").
--
-- MLB's 2026 team list (statsapi.mlb.com/api/v1/teams, sports 1, 11-14, 16,
-- 17 and 23) has 350 teams; 175 had no teamid link. MLB's 2027 list has no
-- team the 2026 list doesn't (York Revolution drops out).
--
--   - 45 already in the list, linked: 41 with the exact name in the same
--     league (all INDY; Ogden Raptors to its INDY row 12390, not the old
--     ROOKIE 10326) and 4 the same team spelled differently, same league:
--     Quebec Capitales = Equipe Quebec Capitales (12385), Tri-City ValleyCats
--     = Tri-City Valley Cats (12394), Staten Island Ferry Hawks = Staten
--     Island FerryHawks (12411), Washington Wild Things = Washington
--     WildThings (10612).
--   - 130 new rows, teamid = 900000 + MLB team id (teams The Baseball Cube
--     doesn't list): 56 ROOKIE (Dominican Summer League, and the 2026 ACL/FCL
--     Brewers, Giants, Royals, Pirates, Tigers and Orioles - MLB has one team
--     each where the list had two), 8 INDY (Pioneer League, Pennsylvania Road
--     Warriors), and Pete's levels: Arizona Fall League = MLB (6); Mexican
--     League (20), winter leagues and Caribbean Series (40) = INTERNATIONAL.
--     The old city-only Mexican League rows ("Monterrey", three "Tijuana"
--     ...) are left alone: nothing says which era each one is.
--
-- Safe to re-run: existing teamids and MLB ids are skipped.
CREATE TEMP TABLE new_teams AS
SELECT e->>0 AS teamid, e->>1 AS name, e->>2 AS org, e->>3 AS level, (e->>4)::int AS mlb_id, e->>5 AS mlb_sport
  FROM jsonb_array_elements($j$[["900406","ACL Brewers","Milwaukee Brewers","ROOKIE",406,"Rookie / Arizona Complex League"],["900408","ACL Giants","San Francisco Giants","ROOKIE",408,"Rookie / Arizona Complex League"],["900412","ACL Royals","Kansas City Royals","ROOKIE",412,"Rookie / Arizona Complex League"],["900434","Bravos de Leon","Mexican League","INTERNATIONAL",434,"Independent Leagues / Mexican League"],["900442","Olmecas de Tabasco","Mexican League","INTERNATIONAL",442,"Independent Leagues / Mexican League"],["900444","Idaho Falls Chukars","Pioneer League","INDY",444,"Independent Leagues / Pioneer League"],["900447","Algodoneros Union Laguna","Mexican League","INTERNATIONAL",447,"Independent Leagues / Mexican League"],["900454","Glendale Desert Dogs","Arizona Fall League","MLB",454,"Winter Leagues / Arizona Fall League"],["900470","FCL Pirates","Pittsburgh Pirates","ROOKIE",470,"Rookie / Florida Complex League"],["900473","FCL Tigers","Detroit Tigers","ROOKIE",473,"Rookie / Florida Complex League"],["900480","Boise Hawks","Pioneer League","INDY",480,"Independent Leagues / Pioneer League"],["900490","Peoria Javelinas","Arizona Fall League","MLB",490,"Winter Leagues / Arizona Fall League"],["900496","Leones de Yucatan","Mexican League","INTERNATIONAL",496,"Independent Leagues / Mexican League"],["900502","Saraperos de Saltillo","Mexican League","INTERNATIONAL",502,"Independent Leagues / Mexican League"],["900513","Billings Mustangs","Pioneer League","INDY",513,"Independent Leagues / Pioneer League"],["900518","Missoula PaddleHeads","Pioneer League","INDY",518,"Independent Leagues / Pioneer League"],["900520","Pericos de Puebla","Mexican League","INTERNATIONAL",520,"Independent Leagues / Mexican League"],["900523","Piratas de Campeche","Mexican League","INTERNATIONAL",523,"Independent Leagues / Mexican League"],["900527","Salt River Rafters","Arizona Fall League","MLB",527,"Winter Leagues / Arizona Fall League"],["900528","Rieleros de Aguascalientes","Mexican L