INSERT INTO public.teamid_universe_mapping (teamid, current_team_name, current_org_or_conference_name, level_label, source_system, current_team_source_team_id, notes)
SELECT teamid, name, org, level, 'mlb_stats_api', mlb_id::text,
       format('2026-10-27: added at Pete''s direction so every team MLB''s feed can send has a teamid and an official level. MLB Stats API team %s (%s). Level %s: %s teamid = 900000 + MLB team id (a team The Baseball Cube does not list).',
              mlb_id, mlb_sport, level,
              CASE level WHEN 'ROOKIE' THEN 'MLB''s Rookie level.' WHEN 'INDY' THEN 'an independent league.'
                         WHEN 'MLB' THEN 'Pete: the Arizona Fall League counts at MLB.'
                         ELSE 'Pete: the Mexican League, the winter leagues and the Caribbean Series count at INTERNATIONAL.' END)
  FROM new_teams
 WHERE NOT EXISTS (SELECT 1 FROM public.teamid_universe_mapping u WHERE u.teamid = new_teams.teamid);

-- A link is made only where our row is INDY in the same league MLB names.
INSERT INTO public.team_id_map (tbc_teamid, team_name, mlb_stats_api_id, source, updated_at)
SELECT teamid, name, mlb_id, 'mlb_stats_api_team_list_20261027', now() FROM new_teams
 WHERE mlb_id NOT IN (SELECT mlb_stats_api_id FROM public.team_id_map WHERE mlb_stats_api_id IS NOT NULL)
UNION ALL
SELECT l.teamid, l.name, l.mlb_id, l.source, now()
  FROM link_teams l
  JOIN public.teamid_universe_mapping u ON u.teamid = l.teamid AND u.current_org_or_conference_name = l.mlb_league AND u.level_label = 'INDY'
 WHERE l.mlb_id NOT IN (SELECT mlb_stats_api_id FROM public.team_id_map WHERE mlb_stats_api_id IS NOT NULL);

-- The lines that were waiting on these teams land with their levels.
SELECT public.stat_lines_reland_held();
